"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _identifier_key(ident):
    """Numeric identifiers sort before alphanumeric ones; each group
    compares naturally (integers numerically, strings in ASCII order)."""
    if ident.isdigit():
        return (0, int(ident), "")
    return (1, 0, ident)


def _precedence_key(version):
    """Build a key so that Python's tuple ordering matches SemVer precedence."""
    # Build metadata is ignored for ordering.
    core_and_pre = version.split("+", 1)[0]
    if "-" in core_and_pre:
        core, pre = core_and_pre.split("-", 1)
    else:
        core, pre = core_and_pre, None

    major, minor, patch = (int(part) for part in core.split("."))

    if pre is None:
        # A release outranks any pre-release of the same core version.
        return (major, minor, patch, 1, ())

    pre_key = tuple(_identifier_key(ident) for ident in pre.split("."))
    # A shorter identifier list is lower when all shared identifiers are equal;
    # tuple comparison already gives this behaviour.
    return (major, minor, patch, 0, pre_key)


def sort_versions(vs):
    """Return the version strings in ``vs`` sorted lowest precedence first.

    Versions that compare equal (e.g. differing only in build metadata)
    keep their input order, since Python's sort is stable.
    """
    return sorted(vs, key=_precedence_key)
